let source = "";
for await (const chunk of process.stdin) source += chunk;
const input = JSON.parse(source || "{}");

const id = input.documentId;
const title = input.title;
const timestamp = input.timestamp;
const key = input.idempotencyKey;
const vendorStatus = input.vendorStatus ?? 200;
const headers = { "content-type": "application/json" };
const doc = { id, title, createdAt: timestamp };

function out(o) {
  console.log(JSON.stringify({
    http: o.http,
    database: o.database ?? { rows: [], transaction: { committed: false, rolledBack: false } },
    messages: o.messages ?? [],
    outbound: o.outbound ?? [],
    ordering: o.ordering ?? [],
    failures: o.failures ?? [],
    retryability: o.retryability ?? false
  }));
}

if (input.replay === true || input.replayed === true) {
  out({
    http: { status: 200, headers: { ...headers, "idempotent-replay": "true" }, body: doc },
    database: { rows: [], transaction: { committed: false, rolledBack: false } },
    ordering: ["idempotency.lookup"]
  });
} else if (!title || typeof title !== "string" || !id) {
  out({
    http: { status: 400, headers, body: { error: "invalid_request" } },
    failures: [{ type: "validation", code: "invalid_request" }]
  });
} else {
  const outbound = [
    { vendor: "authorize", documentId: id, timestamp, idempotencyKey: key },
    { vendor: "index", documentId: id, title, timestamp, idempotencyKey: key }
  ];
  if (vendorStatus >= 200 && vendorStatus < 300) {
    out({
      http: { status: 201, headers, body: doc },
      database: { rows: [{ id, title, createdAt: timestamp, idempotencyKey: key }], transaction: { committed: true, rolledBack: false } },
      messages: [{ type: "document.created", documentId: id, title, occurredAt: timestamp }],
      outbound,
      ordering: ["vendor.authorize", "vendor.index", "db.commit", "event.emit"],
      failures: [],
      retryability: false
    });
  } else {
    const retryable = vendorStatus === 429 || vendorStatus === 408 || vendorStatus >= 500;
    const authz = vendorStatus === 401 || vendorStatus === 403;
    const status = retryable ? 503 : 502;
    const code = authz ? "vendor_unauthorized" : retryable ? "vendor_unavailable" : "vendor_rejected";
    out({
      http: { status, headers, body: { error: code } },
      outbound: [outbound[0]],
      ordering: ["vendor.authorize"],
      failures: [{ type: "vendor", code, vendorStatus }],
      retryability: retryable
    });
  }
}

